        {
          "year": 2024,
          "text": "Russian offensive north of Kharkiv towards Vovchansk (10 May)."
        },
        {
          "year": 2024,
          "text": "Ukrainian incursion into Russia's Kursk Oblast (6 August)."
        },
        {
          "year": 2024,
          "text": "Vuhledar falls (1 October); North Korean troops deployed to Kursk Oblast (October-November); Russian advance on Pokrovsk."
        }
